1	package command
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// Suggestion represents a command suggestion
9	type Suggestion struct {
10		Text     string // Command text: "status", "s", "ctx list"
11		Display  string // Display format: "s (status)", "ctx list"
12		IsAlias  bool   // true for aliases like "s", "ga"
13		FullName string // Full name if alias: "status" for "s"
14		Priority int    // Sort priority (1=exact, 2=alias, 3=full)
15	}
16	
17	// CompletionEngine manages command suggestions
18	type CompletionEngine struct {
19		commands []Suggestion // Pre-built list of suggestions
20	}
21	
22	// NewCompletionEngine creates a new completion engine with all available commands
23	func NewCompletionEngine() *CompletionEngine {
24		engine := &CompletionEngine{}
25		engine.buildCommands()
26		return engine
27	}
28	
29	// buildCommands derives the suggestion list from the parser, which is the
30	// only source: everything that can be typed can be completed, and nothing else.
31	func (ce *CompletionEngine) buildCommands() {
32		fullNames := FullNames()
