135			}
136		}
137	
138		lines := make([]string, headerMinHeight)
139		for i := 0; i < headerMinHeight; i++ {
140			if i < len(info) {
141				// Pad key to maxKeyLen so all ": " align
142				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
143				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
144	
145				value := info[i].Value
146				if info[i].Style.GetForeground() != lipgloss.Color("") {
147					value = info[i].Style.Background(theme.ColorBackground).Render(value)
148				} else {
149					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
150				}
