230	// buildLogoLines builds the logo lines for column 3, vertically centered
231	func buildLogoLines(col3Width int) []string {
232		logoStyle := lipgloss.NewStyle().
233			Background(theme.ColorBackground).
234			Foreground(theme.ColorPrimary).
235			Bold(true)
