1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8		"github.com/anthnel/devdesk/internal/ui/theme"
9		"github.com/charmbracelet/lipgloss"
10	)
11	
12	// HeaderView is the interface each view must implement to provide the header data
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// FramelessView is implemented by a view that draws its own frames and wants
28	// none around it. The default — framed — is the safe behavior: a view that
29	// does not implement this is framed like all the others, unlike HeaderView
30	// whose missing half silently renders an empty title.
31	//
32	// Only one view implements it (the dashboard), and that is deliberate: every
33	// other view frames a single object — a table, a form.
34	type FramelessView interface {
35		Frameless() bool
36	}
37	
38	// headerMinHeight is the fixed header height (without the command line).
39	const headerMinHeight = 7
40	
41	// ASCII logo for the header
42	var logoLines = []string{
43		`    ____            ____            __  `,
44		`   / __ \___ _   __/ __ \___  _____/ /__`,
45		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
46		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
47		`/_____/\___/|___/_____/\___/____/_/|_|  `,
48	}
49	
50	const logoWidth = 40 // max width of a logo line
51	
52	// renderHeader generates the header (fixed height) followed by the command line (1 line).
53	func (a *App) renderHeader() string {
54		if view, ok := a.views[a.currentView]; ok {
55			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
56				shortcuts := headerView.GetShortcuts()
57				if a.commandMode && a.viewPicker {
58					shortcuts = viewPickerShortcuts()
59				}
60				info := headerView.GetHeaderInfo(a.currentContext)
61	
62				header := renderHeaderContent(info, shortcuts, a.width)
63	
64				pad := theme.Bg(" ")
65				var cmdLine string
66				if a.commandMode && a.viewPicker {
67					cmdLine = a.renderViewPicker(a.width)
68				} else if a.commandMode {
69					cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.renderCommandLineWithCompletion()) + pad
70				} else {
71					cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render("❯") + pad
72				}
73	
74				// A blank line under the command line keeps it from touching the title rule.
75				return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine + "\n" + theme.EmptyLineBg(a.width)
76			}
77		}
78	
79		return ""
80	}
81	
82	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
83	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
84	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
85		innerWidth := width - 2 // 1 padding each side
86	
87		// Column widths
88		col1Width := innerWidth / 4
89		col3Width := logoWidth
90		col2Width := innerWidth - col1Width - col3Width
91		if col2Width < 0 {
92			col2Width = 0
93		}
94	
95		// Build column 1: key-value info lines
96		col1Lines := buildInfoLines(info, col1Width)
97	
98		// Build column 2: shortcuts
99		col2Lines := buildShortcutLines(shortcuts, col2Width)
100	
101		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
102		col3Lines := buildLogoLines(col3Width)
103	
104		// Assemble rows
105		rows := make([]string, headerMinHeight)
106		for i := 0; i < headerMinHeight; i++ {
107			c1 := ""
108			if i < len(col1Lines) {
109				c1 = col1Lines[i]
110			}
111			c2 := ""
112			if i < len(col2Lines) {
113				c2 = col2Lines[i]
114			}
115			c3 := ""
116			if i < len(col3Lines) {
117				c3 = col3Lines[i]
118			}
119	
120			pad := theme.Bg(" ")
121			row := pad + theme.PadWithBg(c1, col1Width) + theme.PadWithBg(c2, col2Width) + theme.PadWithBg(c3, col3Width) + pad
122			rows[i] = row
123		}
124	
125		return strings.Join(rows, "\n")
126	}
127	
128	// buildInfoLines builds the key-value info lines for column 1, aligning values on the longest key
129	func buildInfoLines(info []shortcut.HeaderInfo, _ int) []string {
130		// Find max key length for alignment
131		maxKeyLen := 0
132		for _, h := range info {
133			if len(h.Key) > maxKeyLen {
134				maxKeyLen = len(h.Key)
135			}
136		}
137	
138		lines := make([]string, headerMinHeight)
139		for i := 0; i < headerMinHeight; i++ {
140			if i < len(info) {
141				// Pad key to maxKeyLen so all ": " align
142				paddedKey := info[i].Key + strings.Repeat(" ", maxKeyLen-len(info[i].Key))
143				label := theme.HeaderKeyStyle.Render(paddedKey + ": ")
144	
145				value := info[i].Value
146				if info[i].Style.GetForeground() != lipgloss.Color("") {
147					value = info[i].Style.Background(theme.ColorBackground).Render(value)
148				} else {
149					value = lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Render(value)
150				}
151	
152				lines[i] = label + value
153			} else {
154				lines[i] = ""
155			}
156		}
157		return lines
158	}
159	
160	// buildShortcutLines builds the shortcut lines for column 2
161	func buildShortcutLines(shortcuts shortcut.Shortcuts, col2Width int) []string {
162		if len(shortcuts) == 0 {
163			lines := make([]string, headerMinHeight)
164			for i := range lines {
165				lines[i] = ""
166			}
167			return lines
168		}
169	
170		// Split shortcuts into columns of maxLine items
171		columns := splitArrayIntoChunks(shortcuts, headerMinHeight)
172	
173		// Get rendered lines for each column
174		var allColumnLines [][]string
175		for i, col := range columns {
176			minH := 0
177			if i == 0 {
178				minH = headerMinHeight
179			}
180			allColumnLines = append(allColumnLines, renderShortcutsColumnLines(col, minH))
181		}
182	
183		// Normalize heights
184		for i := range allColumnLines {
185			for len(allColumnLines[i]) < headerMinHeight {
186				allColumnLines[i] = append(allColumnLines[i], "")
187			}
188		}
189	
190		// Calculate column widths
191		colWidths := make([]int, len(allColumnLines))
192		for ci, colLines := range allColumnLines {
193			for _, line := range colLines {
194				if w := lipgloss.Width(line); w > colWidths[ci] {
195					colWidths[ci] = w
196				}
197			}
198		}
199	
200		sep := "  "
201		sepRendered := theme.Bg(sep)
202	
203		// Build each row
204		result := make([]string, headerMinHeight)
205		for row := 0; row < headerMinHeight; row++ {
206			var line string
207			for ci, colLines := range allColumnLines {
208				if ci > 0 {
209					line += sepRendered
210				}
211				if row < len(colLines) {
212					line += theme.PadWithBg(colLines[row], colWidths[ci])
213				} else {
214					line += theme.EmptyLineBg(colWidths[ci])
215				}
216			}
217			// Clip to the column. PadWithBg cannot do this — it pads a short line and
218			// returns a long one untouched — and a plain slice would cut an escape
219			// sequence in half, which is the hazard Rule 122 is about. MaxWidth
220			// truncates on rune boundaries and leaves the sequences intact.
221			if col2Width > 0 {
222				line = lipgloss.NewStyle().MaxWidth(col2Width).Render(line)
223			}
224			result[row] = line
225		}
226	
227		return result
228	}
229	
230	// buildLogoLines builds the logo lines for column 3, vertically centered
231	func buildLogoLines(col3Width int) []string {
232		logoStyle := lipgloss.NewStyle().
233			Background(theme.ColorBackground).
234			Foreground(theme.ColorPrimary).
235			Bold(true)
236	
237		lines := make([]string, headerMinHeight)
238		// 5 logo lines in 7 header lines → 1 empty line top and bottom
239		offset := 1
240		for i := 0; i < headerMinHeight; i++ {
241			logoIdx := i - offset
