293	// renderCommandLineWithCompletion generates input + preview + hint
294	func (a *App) renderCommandLineWithCompletion() string {
295		inputView := a.commandInput.View()
296	
297		if len(a.completionSuggestions) == 0 {
298			return inputView
299		}
300	
301		current := a.completionSuggestions[a.completionIndex]
302		currentInput := a.commandInput.Value()
303	
304		previewText := ""
305		if strings.HasPrefix(strings.ToLower(current.Text), strings.ToLower(currentInput)) &&
306			len(currentInput) > 0 {
307			previewText = current.Text[len(currentInput):]
308		}
309	
310		cmdBgStyle := lipgloss.NewStyle().Background(theme.ColorCmdLineBg)
311	
312		preview := cmdBgStyle.Foreground(theme.ColorDim).Render(previewText)
313	
314		hint := cmdBgStyle.Foreground(theme.ColorDim).Italic(true).
315			Render(fmt.Sprintf(" %s [%d/%d]",
316				current.Display,
317				a.completionIndex+1,
318				len(a.completionSuggestions)))
319	
320		contentWidth := lipgloss.Width(inputView) + lipgloss.Width(preview)
321		hintWidth := lipgloss.Width(hint)
322		// width - 2 (outer padding) - 1 (slack, so the hint never touches the edge)
323		spacerWidth := (a.width - 3) - contentWidth - hintWidth
324		spacer := ""
325		if spacerWidth > 0 {
326			spacer = cmdBgStyle.Render(strings.Repeat(" ", spacerWidth))
327		}
328	
329		return inputView + preview + spacer + hint
330	}
