// helpViewportMinHeight keeps the overlay usable on a short window; below it
// the border and the scroll hint would leave no room for content.
const helpViewportMinHeight = 10

// helpOverlayMargin is the room the overlay box's border and padding take from
// the window, horizontally and vertically.
const helpOverlayMargin = 6

// maybeOpenHelp opens the help overlay for the active view, unless a field is
// focused — there "?" is a character to type.
func (a *App) maybeOpenHelp(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := a.views[a.currentView]; !ok {
		return a, nil
	}
	if a.inEditMode() {
		return a, a.forwardToActiveView(msg)
	}

	provider, implements := a.views[a.currentView].(help.Provider)
	if !implements {
		return a, nil
	}

	height := max(a.height-helpOverlayMargin, helpViewportMinHeight)
	a.helpViewport = viewport.New(a.width-helpOverlayMargin, height)
	a.helpViewport.KeyMap = arrowOnlyScroll()
	a.helpViewport.SetContent(help.Render(provider.GetHelpContent(), a.width))
	a.showHelp = true
	return a, nil
}

// arrowOnlyScroll strips the vim aliases bubbles/viewport binds by default.
//
// This overlay is the one place that hands a raw key to a viewport, and the
// library's own KeyMap answers j/k/u/d/b/f behind the application's back — so
// the help would have kept scrolling on letters the rest of the application no
// longer treats as navigation (§3.26). A letter is an action now, and an
// overlay is not an exemption from that.
func arrowOnlyScroll() viewport.KeyMap {
	return viewport.KeyMap{
		Up:       key.NewBinding(key.WithKeys("up")),
		Down:     key.NewBinding(key.WithKeys("down")),
		PageUp:   key.NewBinding(key.WithKeys("pgup")),
		PageDown: key.NewBinding(key.WithKeys("pgdown")),
	}
}

// handleHelpKeyMsg handles key presses in the help overlay
func (a *App) handleHelpKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q", "?":
		a.showHelp = false
		return a, nil
	default:
		// Delegate to the viewport for scrolling (up/down / PgUp / PgDn)
		var cmd tea.Cmd
		a.helpViewport, cmd = a.helpViewport.Update(msg)
		return a, cmd
	}
}

// renderHelpOverlay renders an overlay with the current view's help
func (a *App) renderHelpOverlay() string {
	return theme.OverlayBoxStyle().Render(a.helpViewport.View() + "\n")
}
	if a.switchingTo != "" {
		if msg.String() == "ctrl+c" {
			return a, tea.Quit
		}
		return a, nil
	}
	// If an overlay is displayed, handle its navigation
	if a.showHelp {
		return a.handleHelpKeyMsg(msg)
	}
	if a.showContextList {
		return a.handleContextListKeyMsg(msg)
	}

	if a.commandMode {
		return a.handleCommandMode(msg)
	}

	switch msg.String() {
	case "ctrl+c":
		return a, tea.Quit
	case "q":
		cmd := a.maybeQuitApplication(msg)
		return a, cmd
	case "?":
		return a.maybeOpenHelp(msg)
	case commandModeKey:
		// The authoritative way in: handled here, before any InEditMode() check,
		// so no text input can claim it. A bare ":" cannot play that role — it is
		// an ordinary character in a field holding https://trivy-server:4954.
		return a, a.enterCommandMode()
	case ":":
		cmd := a.maybeEnterInCommandMode(msg)
		return a, cmd
	// esc is deliberately absent: it belongs to the view. The router used to
	// answer it whenever the view was not editing, which made esc-to-go-back dead
	// code everywhere and forced views that wanted it to claim they were editing
	// — a predicate about focused fields, overloaded into one about key
	// ownership (§1.3 D15).
	//
	// Nothing is lost by handing it over: command mode is already closed by the
	// time this switch runs (handleCommandMode answers first), so the router had
	// nothing left to close.
	default:
		return a, a.forwardToActiveView(msg)
	}
}

// forwardToActiveView hands a message to the current view and re-measures the
// layout when the view's footer changed shape in response (Rule 124) — opening
// a filter bar is the case that matters.
func (a *App) forwardToActiveView(msg tea.Msg) tea.Cmd {
	view, ok := a.views[a.currentView]
	if !ok {
		return nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[a.currentView] = updatedView
	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return cmd
}

// enterCommandMode opens the command line unconditionally and asks for a
// re-layout, since the command line replaces the inactive prompt.
//
// Focus is taken here rather than while rendering: a bubbles/textinput drops
// every key it receives while blurred, so granting focus from View() would make
// the command line depend on a render having happened first (Rule 110 — View()
// is read-only).
func (a *App) enterCommandMode() tea.Cmd {
	a.commandMode = true
	a.viewPicker = false
	a.commandInput.Reset()
	a.commandInput.Focus()
	return a.requestResize()
}

