		// so no text input can claim it. A bare ":" cannot play that role — it is
		// an ordinary character in a field holding https://trivy-server:4954.
		return a, a.enterCommandMode()
	case ":":
		cmd := a.maybeEnterInCommandMode(msg)
		return a, cmd
	// esc is deliberately absent: it belongs to the view. The router used to
	// answer it whenever the view was not editing, which made esc-to-go-back dead
	// code everywhere and forced views that wanted it to claim they were editing
	// — a predicate about focused fields, overloaded into one about key
	// ownership (§1.3 D15).
	//
	// Nothing is lost by handing it over: command mode is already closed by the
	// time this switch runs (handleCommandMode answers first), so the router had
	// nothing left to close.
	default:
		return a, a.forwardToActiveView(msg)
	}
}

// forwardToActiveView hands a message to the current view and re-measures the
// layout when the view's footer changed shape in response (Rule 124) — opening
// a filter bar is the case that matters.
func (a *App) forwardToActiveView(msg tea.Msg) tea.Cmd {
	view, ok := a.views[a.currentView]
	if !ok {
		return nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[a.currentView] = updatedView
	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return cmd
}

// enterCommandMode opens the command line unconditionally and asks for a
// re-layout, since the command line replaces the inactive prompt.
//
// Focus is taken here rather than while rendering: a bubbles/textinput drops
// every key it receives while blurred, so granting focus from View() would make
// the command line depend on a render having happened first (Rule 110 — View()
// is read-only).
func (a *App) enterCommandMode() tea.Cmd {
	a.commandMode = true
	a.viewPicker = false
	a.commandInput.Reset()
	a.commandInput.Focus()
	return a.requestResize()
}

// inEditMode reports whether the active view has a focused field, which is what
// decides whether the router claims a key or passes it on.
# Commands

Press `ctrl+p` (or `:` when no text field has focus) to open the command
line, then type any of these:

| Command | Alias | Switches to |
|---|---|---|
| `dashboard` | `d` | Dashboard |
| `status` | `s` | Status |
| `git-auth` | `ga` | Forge authentication view |
| `git-explorer` | `ge` | Forge explorer view |
| `workspaces` | `ws`, `w` | Workspaces |
| `security` | `sec` | Security scanner |
| `templates` | `tpl` | Repository template catalog |
| `containers` | `cont`, `ct` | Containers |
| `oci-resources` | `oci` | OCI Resources |
| `netdiag` | `net` | Network Diagnostics (Diagnostics, Ports, Interfaces and Forward tabs) |
| `configuration` | `config`, `cfg` | Configuration |
| `jobs` | `j` | Jobs |
| `about` | `version` | Build info |
| `context <name>` | `ctx <name>` | Switch to context `<name>` |
| `context list` | | List available contexts |
| `quit` | `q` | Exit |

One spelling per command — there is no forge-prefixed alternative
(`gitlab-auth`, `github-explorer`, …) and no second short form to remember.

!!! note "Where this list comes from"
    This table is generated from `internal/command/parser.go`'s `viewNames`
    map, and a test (`TestEveryDocumentedCommandParsesToWhatItClaims` in
    `internal/command/doc_test.go`) checks it against the authoritative copy
    in `docs/architecture/app-shell.md` on every change — so it can't drift
    silently the way it once did.

## `ctrl+p` vs `:`

`ctrl+p` is handled before any form's edit mode can claim it, so it always
opens the command line, from anywhere. A bare `:` does the same, but only
when nothing is focused — inside a text field it's an ordinary character,
which values like `https://trivy-server:4954` need.

## CLI subcommands

The `dk` binary itself takes one subcommand:

| Subcommand | Runs |
|---|---|
| `dk` (no argument) | The full TUI |
| `dk setup` | A standalone context-creation wizard — see [Run the setup wizard](../how-to/run-the-setup-wizard.md) |

There is no flag-parsing framework behind this — `setup` is a single literal
match on `os.Args[1]`, and it's the one thing that has to run *before* any
context is loaded, since it's what creates the first one.
